"""All14 estimable original CM contexts; no selection by programme association p."""
from pathlib import Path
from datetime import datetime,timezone
import os,json,hashlib,gzip,gc,shutil
import numpy as np,pandas as pd,zarr
from scipy.sparse import csr_matrix,vstack
from scipy.io import mmwrite
from sklearn.decomposition import PCA

def sha(p):
 h=hashlib.sha256()
 with Path(p).open('rb') as f:
  for b in iter(lambda:f.read(8388608),b''):h.update(b)
 return h.hexdigest()
def main():
 R=Path(os.environ['PANCANCER_PREFLIGHT_ROOT']);AR=Path(os.environ['PANCANCER_ANNOTATION_ROOT']);V=Path(os.environ['PANCANCER_STATE_MODEL_OUTPUT_ROOT']);P=Path('/tmp/state_after_DIALOGUE_plan_v2.json');plan=json.loads(P.read_text());assert sha(__file__)==plan['preparer_sha256'];C=V/'original_CM_programme_pair_associations_20261015_v2/all_context_coverage_reasons.tsv';assert sha(C)==plan['coverage_sha256'];contexts=pd.read_csv(C,sep='\t',keep_default_na=False);contexts=contexts[contexts.status.eq('ESTIMABLE')].sort_values('context');assert len(contexts)==14;F=R/'all_CM_state_native_input_preflight_20261014_v1';fi=json.loads((F/'inventory.json').read_text());U=F/'private_all_frozen_sample_node_units.tsv.gz';assert sha(U)==fi['private_unit_table_sha256'];u=pd.read_csv(U,sep='\t',keep_default_na=False);assert sha(F/'private_canonical_row_selection.npz')==fi['private_row_selection_sha256'];z=np.load(F/'private_canonical_row_selection.npz');rows=z['global_rows'];uids=z['unit_index'];assert len(rows)==4532933
 UC=AR/'20261010_uniform_expression_annotation_v1';assert sha(UC/'input_contract.json')==plan['canonical_contract_sha256'];contract=json.loads((UC/'input_contract.json').read_text());g=zarr.open_group(contract['core_zarr'],mode='r');x=g['X'];coregenes=contract['raw_shape'][1];key=g['obs'].attrs['_index'];scope=pd.read_csv(F/'all_source_native_scope.tsv',sep='\t').set_index('gse_id');assert shutil.disk_usage(V).free>500*2**30;O=V/'state_after_DIALOGUE_inputs_20261016_v2';assert not O.exists();O.mkdir(mode=0o700);summary=[];invent=[]
 for r in contexts.itertuples():
  ctx=f'context_{int(r.context):04}';out=O/ctx;out.mkdir(mode=0o700);a=u[u.subCluster.eq(r.endpoint_A)&u.stratum.eq(r.stratum)&u.gse_id.eq(r.gse_id)];b=u[u.subCluster.eq(r.endpoint_B)&u.stratum.eq(r.stratum)&u.gse_id.eq(r.gse_id)];j=a.merge(b,on=['sample_uid','gse_id','stratum','effective_resampling_block'],suffixes=('_A','_B'),validate='one_to_one');j=j[(j.n_cells_A>=20)&(j.n_cells_B>=20)&j.analysis_eligible_A&j.analysis_eligible_B].copy();j=j.sort_values(['effective_resampling_block','sample_uid']).drop_duplicates('effective_resampling_block');assert len(j)==int(r.analysis_blocks);blocks=np.sort(j.effective_resampling_block.to_numpy(str));rng=np.random.default_rng(plan['seed']+int(r.context));holdout=set(rng.choice(blocks,max(10,len(blocks)//3),replace=False)) if len(blocks)>=30 else set();j['partition']=j.effective_resampling_block.map(lambda t:'holdout' if t in holdout else 'discovery');mode='BLOCK_HOLDOUT' if holdout else 'EXPLORATORY_NO_HOLDOUT';assert j[j.partition.eq('discovery')].shape[0]>=20;assert not set(j[j.partition.eq('discovery')].effective_resampling_block)&set(j[j.partition.eq('holdout')].effective_resampling_block);j.to_csv(out/'private_block_library_partition.tsv',sep='\t',index=False)
  gp=UC/'by_gse'/r.gse_id/'genes.tsv';assert sha(gp)==scope.loc[r.gse_id,'native_gene_axis_sha256'];gt=pd.read_csv(gp,sep='\t');genes=gt.gene.to_numpy(str);cols=gt.core_column.to_numpy(int);allowed=np.zeros(coregenes,bool);allowed[cols]=True
  for side in ['A','B']:
   selected=[];meta=[]
   for row in j.itertuples():
    unit=int(getattr(row,'unit_index_'+side));positions=np.flatnonzero(uids==unit);assert len(positions)==int(getattr(row,'n_cells_'+side));chosen=np.sort(rng.choice(positions,min(len(positions),plan['max_cells_per_block_type']),replace=False));selected.extend(rows[chosen].tolist());meta.extend(dict(global_row=int(q),block=row.effective_resampling_block,sample_uid=row.sample_uid,unit_index=unit,partition=row.partition,reviewed_patient=getattr(row,'unit_kind_'+side)=='reviewed_patient') for q in rows[chosen])
   md=pd.DataFrame(meta).sort_values('global_row').reset_index(drop=True);rr=md.global_row.to_numpy(int);assert len(np.unique(rr))==len(rr);parts=[];start=0
   while start<len(rr):
    end=min(start+500,len(rr),int(np.searchsorted(rr,rr[start]+5000,side='left')));assert end>start;take=rr[start:end];lo=int(take[0]);hi=int(take[-1])+1;ip=np.asarray(x['indptr'][lo:hi+1],np.int64);aa,bb=int(ip[0]),int(ip[-1]);raw=csr_matrix((x['data'][aa:bb],x['indices'][aa:bb],ip-aa),shape=(hi-lo,coregenes))[take-lo].tocsr();raw.sort_indices();assert raw.has_canonical_format and allowed[raw.indices].all();parts.append(raw[:,cols].astype(np.float64));start=end
   raw=vstack(parts,format='csr');total=np.asarray(raw.sum(1)).ravel();det=np.asarray((raw>0).sum(1)).ravel();assert (total>0).all();cell=np.asarray(g['obs'][key].get_orthogonal_selection((rr,)).tolist(),dtype=str);assert len(set(cell))==len(cell);md['cell']=cell;md['sample']=md.block
   cp=raw.copy();cp.data*=np.repeat(10000/total,np.diff(cp.indptr));cp.data=np.log1p(cp.data);train=md.partition.eq('discovery').to_numpy();active=(np.asarray((raw[train]>0).mean(0)).ravel()>=.01)&~pd.Index(genes).str.match(r'^(MT-|RPL|RPS)');ix=np.flatnonzero(active);X=cp[:,ix];mu=np.asarray(X[train].mean(0)).ravel();var=np.asarray(X[train].power(2).mean(0)).ravel()-mu**2;positive=np.flatnonzero(var>1e-12);assert len(positive)>=2000;hvg=positive[np.argsort(-var[positive],kind='stable')[:2000]];pca=PCA(n_components=20,svd_solver='randomized',random_state=plan['seed']);pca.fit(X[train][:,hvg].toarray());pc=pca.transform(X[:,hvg].toarray());quality=np.column_stack([np.log1p(total),np.log1p(det)]);qm=quality[train].mean(0);qs=quality[train].std(0);assert (qs>0).all();qq=(quality-qm)/qs;md['cellQ']=qq[:,0];md['geneQ']=qq[:,1]
   for part in ['discovery','holdout']:
    mask=md.partition.eq(part).to_numpy()
    if not mask.any():continue
    prefix=out/('type'+side+'_'+part)
    with gzip.open(str(prefix)+'_tpm.mtx.gz','wb',compresslevel=3) as f:mmwrite(f,X[mask].T)
    md.loc[mask].to_csv(str(prefix)+'_metadata.tsv',sep='\t',index=False);pd.DataFrame(pc[mask],index=cell[mask],columns=['PC'+str(q+1) for q in range(20)]).to_csv(str(prefix)+'_PC.tsv',sep='\t');pd.Series(genes[ix]).to_csv(str(prefix)+'_genes.tsv',sep='\t',header=False,index=False);summary.append(dict(context=int(r.context),side=side,gse_id=r.gse_id,endpoint=getattr(r,'endpoint_'+side),mode=mode,partition=part,blocks=int(md.loc[mask,'block'].nunique()),cells=int(mask.sum()),genes=len(ix),PCs=20,reviewed_patient_blocks=int(md.loc[mask&md.reviewed_patient,'block'].nunique())))
   np.savez_compressed(out/('type'+side+'_frozen_transform.npz'),PCA_components=pca.components_,PCA_mean=pca.mean_,HVG_genes=genes[ix[hvg]],gene_names=genes[ix],quality_mean=qm,quality_sd=qs);del raw,cp,X,parts;gc.collect()
  files={p.name:sha(p) for p in out.iterdir() if p.is_file()};(out/'private_input_inventory.json').write_text(json.dumps(dict(context=int(r.context),gse_id=r.gse_id,stratum=r.stratum,endpoints=[r.endpoint_A,r.endpoint_B],mode=mode,files=files),indent=2)+'\n');invent.append(dict(context=int(r.context),relative_dir=ctx,input_inventory_sha256=sha(out/'private_input_inventory.json'),mode=mode));(O/'progress.json').write_text(json.dumps(dict(completed_contexts=len(invent),observed_UTC=datetime.now(timezone.utc).isoformat()))+'\n')
 pd.DataFrame(summary).to_csv(O/'public_input_scope_summary.tsv',sep='\t',index=False);iv=dict(status='PREPARED_ALL14_STATE_AFTER_DIALOGUE_CONTEXT_INPUTS_NOT_MODELS',observed_UTC=datetime.now(timezone.utc).isoformat(),producer_sha256=sha(__file__),plan_sha256=sha(P),context_coverage_sha256=sha(C),contexts=invent,patient_outcomes_used=False,clinical_statistics_used=False,all_contexts_selected_by_coverage_not_programme_P=True,public_summary_sha256=sha(O/'public_input_scope_summary.tsv'));(O/'inventory.json').write_text(json.dumps(iv,indent=2)+'\n');print(json.dumps({k:v for k,v in iv.items() if k!='contexts'}))
if __name__=='__main__':main()
